<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {copyText,changedEvent,api,mutate,can,text,date,opts,useTask,type DTO,type Page} from './shared';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';import AdminDialog from '../../shared/ui/AdminDialog.vue';import {accountSettingsOpen,authSession} from '../identity/session';
type Account=DTO<'IdentityAccountPage'>['items'][number];
const {busy,error,notice,run}=useTask(),{form,open}=useForm(),tab=ref('personal'),pref=ref<DTO<'Stage2NotificationPreferenceView'>>(),accounts=ref<Account[]>([]),departments=ref<DTO<'IdentityDepartmentView'>[]>([]),people=ref<DTO<'Stage2PersonPickerOption'>[]>([]),page=ref(1),total=ref(0),more=ref(false),issued=ref<DTO<'IdentityTokenIssuedView'>>();let timer:ReturnType<typeof setTimeout>;
function hide(){issued.value=undefined;clearTimeout(timer);}function visibility(){if(document.hidden)hide();}document.addEventListener('visibilitychange',visibility);onBeforeUnmount(()=>{hide();document.removeEventListener('visibilitychange',visibility);});
async function load(){await run(async()=>{if(tab.value==='personal')pref.value=await api.get<DTO<'Stage2NotificationPreferenceView'>>('/me/notification-preferences');else {const endpoint=tab.value==='accounts'?'/admin/accounts':tab.value==='departments'?'/admin/departments':'/people';const d=await api.get<Page<Account|DTO<'IdentityDepartmentView'>|DTO<'Stage2PersonPickerOption'>>>(endpoint+'?page='+page.value);total.value=d.pagination.total;more.value=d.pagination.has_next;if(tab.value==='accounts')accounts.value=d.items as Account[];if(tab.value==='departments')departments.value=d.items as DTO<'IdentityDepartmentView'>[];if(tab.value==='people')people.value=d.items as DTO<'Stage2PersonPickerOption'>[];}});}
function changeTab(v:string){tab.value=v;page.value=1;void load();}onMounted(load);
function showToken(value:DTO<'IdentityTokenIssuedView'>){hide();issued.value=value;timer=setTimeout(hide,60000);}
function account(a?:Account){open({title:a?'维护登录账号':'创建登录账号',description:'登录角色与业务资源归属分别管理；停用账号会使会话失效，但不自动回收业务资源。',fields:[...(!a?[{key:'username',label:'登录用户名',required:true,hint:'3—64 位小写字母、数字及 . _ -'},{key:'person_id',label:'关联已有人员（可选）',endpoint:'/people'}]:[]),{key:'display_name',label:'姓名',required:true,initial:a?.display_name},{key:'department_id',label:'所属部门（可选）',endpoint:'/departments',initial:a?.department_id??''},{key:'role',label:'登录角色',required:true,options:opts(['member','resource_manager','admin']),initial:a?.role??'member'},...(a&&a.status!=='pending'?[{key:'status',label:'账号状态',required:true,options:opts(['active','inactive']),initial:a.status}]:[])],onSubmit:async v=>{const body={...v,department_id:v.department_id||null,...(a?{expected_version:a.version}:{person_id:v.person_id||null})};if(a)await mutate('/admin/accounts/'+a.id,body,'PATCH');else showToken(await mutate<DTO<'IdentityTokenIssuedView'>>('/admin/accounts',body));await load();}});}
function recovery(a:Account){open({title:'签发一次性恢复令牌',description:'将撤销该账号现有会话及旧令牌；新令牌只显示一次，请由你安全交给本人。',fields:[],submitLabel:'签发并撤销旧会话',onSubmit:async()=>{showToken(await mutate<DTO<'IdentityTokenIssuedView'>>(`/admin/accounts/${a.id}/recovery-token`));await load();}});}
function scope(a:Account,removeIndex?:number){open({title:removeIndex===undefined?'增加数据范围':'移除数据范围',description:'数据范围控制可见与可管理的对象；资源角色和凭据查看授权仍分别生效。',fields:removeIndex===undefined?[{key:'kind',label:'范围类别',required:true,options:opts(['department','resource']),initial:'resource'},{key:'target_id',label:'目标对象',required:true,endpoint:(v:Record<string,string>)=>v.kind==='department'?'/departments':'/resources'},{key:'permission',label:'范围权限',required:true,options:[{value:'read',label:'查阅'},{value:'manage',label:'管理'}],initial:'read'}]:[],onSubmit:async v=>{const scopes=removeIndex===undefined?[...a.scopes,{kind:v.kind,target_id:v.target_id,permission:v.permission}]:a.scopes.filter((_,i)=>i!==removeIndex);await mutate('/admin/accounts/'+a.id,{expected_version:a.version,scopes},'PATCH');await load();}});}
function department(d?:DTO<'IdentityDepartmentView'>){open({title:d?'维护部门':'新建部门',fields:[{key:'name',label:'部门名称',required:true,initial:d?.name},{key:'parent_id',label:'上级部门（可选）',endpoint:'/departments',initial:d?.parent_id??''},...(d?[{key:'status',label:'状态',required:true,options:opts(['active','inactive']),initial:d.status}]:[])],onSubmit:async v=>{await mutate(d?'/admin/departments/'+d.id:'/admin/departments',{...v,parent_id:v.parent_id||null,...(d?{expected_version:d.version}:{})},d?'PATCH':'POST');await load();}});}
function person(){open({title:'登记业务人员',description:'仅建立业务人员，不开通登录账号。需要登录时可在账号创建中关联此人员。',fields:[{key:'display_name',label:'姓名',required:true},{key:'department_id',label:'所属部门',endpoint:'/departments'}],onSubmit:async v=>{await mutate('/people',{...v,department_id:v.department_id||null});await load();}});}
async function editPerson(p:DTO<'Stage2PersonPickerOption'>){await run(async()=>{const row=await api.get<DTO<'Stage2PersonView'>>('/people/'+p.id);open({title:'维护业务人员',description:'已关联登录账号的人员信息请在账号管理中维护。',fields:[{key:'display_name',label:'姓名',required:true,initial:row.display_name},{key:'department_id',label:'所属部门',endpoint:'/departments',initial:row.department_id??''},{key:'status',label:'状态',options:opts(['active','inactive']),initial:row.status}],onSubmit:async v=>{await mutate('/people/'+p.id,{...v,department_id:v.department_id||null,expected_version:row.version},'PATCH');await load();}});});}
</script>
<template><header class="page-heading"><div><h1>设置与团队</h1><p>个人提醒、登录账号与组织数据；业务资产责任通过治理维护。</p></div><button class="btn-secondary" @click="accountSettingsOpen=true">账号安全与重新验证</button></header><section class="feishu-section"><nav class="flex overflow-x-auto border-b"><button class="task-tab" :class="tab==='personal'?'task-tab-active':''" @click="changeTab('personal')">个人设置</button><template v-if="can('identity.manage')"><button class="task-tab" :class="tab==='accounts'?'task-tab-active':''" @click="changeTab('accounts')">登录账号</button><button class="task-tab" :class="tab==='departments'?'task-tab-active':''" @click="changeTab('departments')">部门</button></template><button v-if="can('directory.manage')" class="task-tab" :class="tab==='people'?'task-tab-active':''" @click="changeTab('people')">业务人员</button></nav><PageState :busy="busy" :error="error" :notice="notice" @retry="load"/><div v-if="tab==='personal'" class="space-y-4 p-4"><h2 class="text-sm font-medium">到期提醒</h2><p class="text-xs text-gray-500">控制提醒标记；不会撤销订阅提醒记录，也不会把资源标为已处理。</p><label v-if="pref" class="flex items-center gap-2 text-sm"><input type="checkbox" :checked="pref.show_due" :disabled="busy||authSession?.read_only" @change="run(async()=>{pref=await mutate<DTO<'Stage2NotificationPreferenceView'>>('/me/notification-preferences',{expected_version:pref!.version,show_due:($event.target as HTMLInputElement).checked},'PATCH');changedEvent();notice='个人设置已保存。';})">显示未读到期提醒标记</label></div><template v-else-if="tab==='accounts'"><div class="toolbar justify-between"><p class="text-xs text-gray-500">登录角色、状态与显式数据范围。</p><button class="btn-primary" @click="account()">创建账号</button></div><div class="admin-table-scroll"><table class="feishu-table min-w-[680px]"><thead><tr><th>人员 / 用户名</th><th>角色 / 状态</th><th>数据范围</th><th>操作</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td>{{a.display_name}}<p class="mt-1 text-gray-500">{{a.username}}</p></td><td>{{text(a.role)}}<p class="mt-1 text-gray-500">{{a.status==='pending'?'待激活':text(a.status)}}</p></td><td><p v-if="!a.scopes.length" class="text-gray-500">默认范围及业务角色</p><details v-if="a.scopes.length"><summary class="cursor-pointer text-gray-600">{{a.scopes.length}} 个显式数据范围</summary><div v-for="(s,i) in a.scopes" :key="i" class="mb-1 flex flex-wrap items-center gap-1"><RouterLink v-if="s.kind==='resource'" :to="'/resources/'+s.target_id" class="text-link">资源详情 · {{s.target_id.slice(0,8)}}</RouterLink><span v-else>{{text(s.kind)}} · {{s.target_id.slice(0,8)}}</span> · {{s.permission==='manage'?'管理':'查阅'}}<button class="text-link" @click="scope(a,i)">移除</button></div></details><button class="text-link" @click="scope(a)">增加范围</button></td><td><div class="flex flex-wrap gap-1"><button class="btn-ghost text-xs" @click="account(a)">维护</button><button class="btn-ghost text-xs" :disabled="a.status==='inactive'" @click="recovery(a)">恢复 / 激活令牌</button></div></td></tr></tbody></table></div></template><template v-else-if="tab==='departments'"><div class="toolbar justify-between"><p class="text-xs text-gray-500">停用前须先处理子部门、人员和资源归属。</p><button class="btn-primary" @click="department()">新建部门</button></div><div v-for="d in departments" :key="d.id" class="flex justify-between gap-2 border-b px-4 py-3 text-sm"><span>{{d.name}} <span class="ml-2 text-xs text-gray-500">{{text(d.status)}}</span></span><button class="text-link text-xs" @click="department(d)">维护</button></div></template><template v-else-if="tab==='people'"><div class="toolbar justify-between"><p class="text-xs text-gray-500">业务人员可以没有登录账号。</p><button class="btn-primary" @click="person">登记人员</button></div><div v-for="p in people" :key="p.id" class="flex justify-between gap-2 border-b px-4 py-3 text-sm"><span>{{p.display_name}} <span class="ml-2 text-xs text-gray-500">{{p.department?.display_name??'无部门'}} · {{text(p.status)}}</span></span><button class="text-link text-xs" @click="editPerson(p)">维护</button></div></template><Pager v-if="tab!=='personal'" :page="page" :total="total" :more="more" @change="page=$event;load()"/></section><AdminDialog :open="Boolean(issued)" title="一次性账号令牌" description="仅在此显示 60 秒，切出页面或关闭即清除。请自行安全交给本人，系统不会代发消息。" title-id="issued-title" @close="hide"><div class="admin-dialog-body"><p class="mb-2 text-sm">{{issued?.account.display_name}} · 有效至 {{date(issued?.expires_at)}}</p><pre class="whitespace-pre-wrap break-all rounded-lg bg-gray-50 p-3 text-sm">{{issued?.action_token}}</pre><p class="mt-3 text-xs text-gray-500">本人在登录页选择“激活 / 恢复”，填写令牌并设置自己的密码。</p></div><footer class="admin-dialog-footer"><button class="btn-secondary" @click="hide">立即隐藏</button><button class="btn-primary" @click="run(async()=>{await copyText(issued!.action_token);notice='已复制一次性令牌。';})">复制令牌</button></footer></AdminDialog><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
